<script>(()=>{const form=document.getElementById('exam-form');const timer=document.getElementById('exam-timer');let seconds={{ (int)$remainingSeconds }};let submitted=false;const fmt=n=>String(n).padStart(2,'0');const tick=()=>{const m=Math.floor(seconds/60),s=seconds%60;timer.textContent=fmt(m)+':'+fmt(s);if(seconds<=0){if(!submitted){submitted=true;timer.textContent='Submitting…';form.submit()}return}seconds-=1};tick();const handle=setInterval(()=>{tick();if(seconds<=0)clearInterval(handle)},1000);form.addEventListener('submit',()=>{submitted=true;document.getElementById('submit-exam').disabled=true;});})();</script></body></html>